False ↔
  ∀ (α : Type) [inst : Fintype α] [inst_1 : DecidableEq α] [Nontrivial α] (G : SimpleGraph α)
    [inst_3 : DecidableRel G.Adj],
    G.Connected →
      have A := {v | G.degree v = G.minDegree};
      have M := {v | G.degree v = G.maxDegree};
      have eccavg := fun S => ↑(∑ v ∈ S, (G.eccent v).toNat) / ↑S.card;
      G.distavg ↑A + 1 / 2 * eccavg M ≤ ↑G.path

(fun x => ∑ n ∈ Finset.Icc 1 x, ↑(Erdos448.tauPlus n)) =Θ[Filter.atTop] fun x =>
  have α := 1 - (1 + Real.log (Real.log 2)) / Real.log 2;
  ↑x * Real.log ↑x ^ (1 - α) / Real.log (Real.log ↑x) ^ (3 / 2)
